def inventory(pattern):
 files=sorted(S.glob(pattern));pages=[read(f)['data'] for f in files];records=sum([p['list'] for p in pages],[]);total=pages[0]['paging']['totalCount'] if pages else None
 complete=bool(pages) and len(pages)==pages[0]['paging']['totalPages'] and len(records)==len({r['id'] for r in records})==total and all(p['paging']['totalCount']==total for p in pages)
 return files,records,complete
