write('OFFICIAL_VN30_UNIVERSE_REVIEW',{'asOf':'2026-10-16','status':status,'authority':'DATED_OFFICIAL_HOSE_NOTICE_PLUS_COMPLETE_SUBSEQUENT_CHANGE_HISTORY','apiAloneCanCertify':False,'announcementDate':'2026-07-15','effectiveDate':'2026-08-03','composition':composition,'uniqueCount':len(set(composition)),'notice':{'url':'https://api.hsx.vn/n/api/v1/1/news/2479382','path':str(S/'notice-curl.json'),'sha256':sha(S/'notice-curl.json'),'retrievalMethod':'macOS curl with system TLS trust; exit0','localFileWriteTimeUTC':datetime.datetime.fromtimestamp((S/'notice-curl.json').stat().st_mtime,datetime.timezone.utc).isoformat(),'timeSemantics':'LOCAL_CAPTURE_FILE_WRITE_TIME_NOT_ISSUER_PUBLICATION'},'originalPDF':{'url':research['members'][0]['sourceReference'],'path':str(S/'july-composition.pdf'),'sha256':sha(S/'july-composition.pdf')},'mainTableEvidence':'JULY_NOTICE_TABLE_REVIEW.json','universeHash':hashlib.sha256(json.dumps(sorted(composition),separators=(',',':')).encode()).hexdigest(),'subsequentHistory':'UNIVERSE_CHANGE_HISTORY.json','postEffectiveConstituentChangeFound':False,'historyComplete':complete and preComplete,'unclassifiedNotices':unknown,'apiDiscrepancy':{'path':str(S/'current-api.json'),'sha256':sha(S/'current-api.json'),'apiOnly':sorted(set(apiNames)-set(composition)),'datedOnly':sorted(set(composition)-set(apiNames)),'resolution':'Undated endpoint does not establish a dated index-review event or effective interval. Complete dated official publication history and main-table composition provide as-of authority; API mismatch is retained as diagnostic, not overwritten or promoted.'},'researchUniverseDifference':{'entering':sorted(set(composition)-set(expected)),'exiting':sorted(set(expected)-set(composition))},'onCompositionChange':'UNIVERSE_CHANGE_REQUIRES_DATA_INITIALIZATION','productionRegistryChanged':False,'DI14Approved':False,'readyForScoring':False,'decisionReady':False,'limitations':[] if status=='CERTIFIED' else ['Date-history or unclassified notice review incomplete; no certification granted.']})
print(status,'history',len(records),'pre',len(preRecords),'unknown',[(r['id'],r['title']) for r in unknown])
